.dm-igx-ef span:nth-child(2){transform:translateY(-6px)}
/* the composer: references, the prompt, its styles, and the settings for the run */
.dm-igx-cmp{flex:none;margin:0 var(--dm-s-3) var(--dm-s-3);display:flex;flex-direction:column;border-radius:var(--dm-r-box);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);transition:box-shadow var(--dm-t-fast)}
.dm-igx-cmp:focus-within{box-shadow:inset 0 0 0 1px var(--dm-field-line-strong)}
.dm-igx-refs{display:flex;flex-wrap:wrap;gap:6px;padding:10px var(--dm-s-3) 0}
.dm-igx-refs:empty{display:none}
.dm-igx-ref{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 var(--dm-s-1) 0 3px;border-radius:var(--dm-r-tag);background:var(--dm-chip);font-size:12px;color:var(--dm-fg2);white-space:nowrap}
