.dm-igx-ta{display:block;width:100%;height:58px;border:0;outline:0;resize:none;background:none;color:var(--dm-fg);font:inherit;font-size:14px;line-height:1.45;padding:var(--dm-s-3) var(--dm-s-3) 2px}
.dm-igx-ta::placeholder{color:var(--dm-muted)}
.dm-igx-sty{display:flex;flex-wrap:wrap;gap:6px;padding:6px var(--dm-s-3) 0}
/* a style chip is a white tile with a dimmed edge; picked, its edge steps up and a tick slides in */
.dm-igx-sc{display:inline-flex;align-items:center;gap:0;height:26px;padding:0 10px;border-radius:var(--dm-r-tag);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 100%,transparent);font-size:12.5px;color:var(--dm-fg2);white-space:nowrap;transition:background var(--dm-t-fast),color var(--dm-t-fast),box-shadow var(--dm-t-fast),gap var(--dm-t) var(--dm-ease)}
