.dm-igx-sc[aria-pressed="true"] .dm-i{width:12px;opacity:1}
.dm-igx-sc.dm-hl{background:var(--dm-row)}
.dm-igx-bar{display:flex;align-items:center;gap:var(--dm-s-1);padding:var(--dm-s-2) var(--dm-s-2) var(--dm-s-2) 6px}
.dm-igx-bar .dm-chip{height:32px;padding:0 10px;gap:6px;background:none;min-width:0;font-size:13px;color:var(--dm-fg2)}
