.dm-igx-bar .dm-chip>span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dm-igx-bar .dm-chip>.dm-i:last-child{color:var(--dm-muted)}
.dm-igx-bar .dm-sp{flex:1}
.dm-igx-go{flex:none}
/* the settings: shape and how many, two switches in a small panel */
.dm-igx-pp-set{min-width:236px;padding:var(--dm-s-2) 10px 10px}
.dm-igx-pp-set .dm-ph{padding:var(--dm-s-1) 0 6px}
.dm-igx-pp-set .dm-seg2{display:flex;margin-bottom:var(--dm-s-1)}
.dm-igx-pp-set .dm-seg2 button{flex:1}
/* the side: earlier pictures and style presets */
.dm-igx-sh{flex:none;display:flex;align-items:center;gap:var(--dm-s-2);height:44px;padding:0 var(--dm-s-2);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-igx-sh .dm-sp{flex:1}
.dm-igx-sh .dm-muted{font-size:12px;padding-right:6px}
.dm-igx-pane{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;padding:var(--dm-s-2)}
.dm-igx-pane[hidden]{display:none}
.dm-igx-pane:focus-visible{outline-offset:-2px}
/* the gallery: two columns, each picture in its own shape, the newest first */
.dm-igx-gal{display:flex;gap:6px;align-items:flex-start}
.dm-igx-col{flex:1;min-width:0;display:flex;flex-direction:column;gap:6px}
.dm-igx-g{position:relative;display:block;width:100%;aspect-ratio:var(--dm-ar,1);border-radius:var(--dm-r-sm);overflow:hidden;background:var(--dm-row);cursor:zoom-in;transition:opacity var(--dm-t-fast)}
.dm-igx-g .dm-igx-ly{transform:scale(var(--dm-vz,1));transform-origin:var(--dm-vo,50% 50%);transition:transform .5s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-igx-g:hover .dm-igx-ly{transform:scale(calc(var(--dm-vz,1) * 1.04))}}
.dm-igx-g:focus-visible{outline-offset:-2px}
.dm-igx-g.dm-new{animation:dm-igxnew .7s var(--dm-ease) both}
@keyframes dm-igxnew{from{opacity:0;filter:blur(8px);transform:translateY(-8px)}to{opacity:1;filter:none;transform:none}}
:root:not([data-style="soft"]) .dm-igx-g.dm-new:not(:where([data-style="soft"],[data-style="soft"] *)){animation:dm-igxwipe var(--dm-t-slow) var(--dm-ease) both}
@keyframes dm-igxwipe{from{clip-path:inset(0 0 100% 0)}to{clip-path:inset(0)}}
/* the style presets: a picture and what it sets */
.dm-igx-prs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}
.dm-igx-pr{display:flex;flex-direction:column;gap:6px;padding:4px 4px 8px;border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 100%,transparent);text-align:left;transition:background var(--dm-t-fast),box-shadow var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-igx-pr:hover{background:var(--dm-row)}}
.dm-igx-pr[aria-pressed="true"]{box-shadow:inset 0 0 0 1px var(--dm-faint)}
.dm-igx-prp{position:relative;display:block;aspect-ratio:4/3;border-radius:var(--dm-r-sm);overflow:hidden;background:var(--dm-row)}
.dm-igx-prt{display:flex;flex-direction:column;padding:0 4px;font-size:12.5px;line-height:1.35}
.dm-igx-prt b{font-weight:500;color:var(--dm-fg)}
.dm-igx-prt .dm-muted{font-size:11.5px}
/* the larger view: over the whole component, the picture as large as it fits, with every action */
.dm-igx-lb{position:absolute;inset:0;z-index:5;display:flex;flex-direction:column;border-radius:var(--dm-r-card);background:var(--dm-surface);box-shadow:var(--dm-shadow);overflow:hidden}
