.dm-igx-lb.dm-open .dm-igx-lbs>.dm-igx-t{animation:dm-igxlbp .6s var(--dm-ease) both}
@keyframes dm-igxlbp{from{opacity:0;transform:scale(.94);filter:blur(10px)}to{opacity:1;transform:none;filter:none}}
:root:not([data-style="soft"]) .dm-igx-lb.dm-open:not(:where([data-style="soft"],[data-style="soft"] *)){animation:dm-igxwipe var(--dm-t-slow) var(--dm-ease) both}
:root:not([data-style="soft"]) .dm-igx-lb.dm-open .dm-igx-lbs>.dm-igx-t:not(:where([data-style="soft"],[data-style="soft"] *)){animation:none}
.dm-igx-lbh{flex:none;display:flex;align-items:center;gap:var(--dm-s-2);min-height:48px;padding:6px var(--dm-s-2) 6px var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-igx-lbt{flex:1;min-width:0;display:flex;flex-direction:column;font-size:13px;line-height:1.35}
.dm-igx-lbt b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-igx-lbt .dm-muted{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-igx-lbb{flex:1;min-height:0;display:flex;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-3) var(--dm-s-2)}
.dm-igx-lbs{flex:1;min-width:0;height:100%;display:flex;align-items:center;justify-content:center;container-type:size}
.dm-igx-lbs>.dm-igx-t{width:min(100cqw,100cqh * var(--dm-ar,1));cursor:default}
.dm-igx-lbn{flex:none;width:32px;padding:0}
@media (hover:hover) and (pointer:fine){.dm-igx-lbn:not(:disabled):hover{background:var(--dm-row)}}
.dm-igx-lbf{flex:none;display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:var(--dm-s-1);padding:var(--dm-s-2) var(--dm-s-3) var(--dm-s-3)}
.dm-igx-lbf .dm-igx-sep{margin:0 var(--dm-s-1)}
.dm-igx-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
/* a narrower feed keeps only the stage in hand beside the title */
@container igx (max-width:780px){.dm-igx-steps span:not(.dm-on){display:none}}
/* between the two, the side gives the pictures a little more room, and a failed picture keeps only its title and Retry */
@container igx (max-width:820px){.dm-igx-in{grid-template-columns:minmax(0,1fr) 212px}.dm-igx-f>span{display:none}}
/* narrower: the gallery and the styles take the feed's place, picked in the header */
@container igx (max-width:620px){
  .dm-igx-in{grid-template-columns:minmax(0,1fr);height:600px}
  .dm-igx-main,.dm-igx-side{grid-area:1/1}
  .dm-igx-side{margin-top:45px;border-radius:0 0 var(--dm-r-card) var(--dm-r-card);box-shadow:none;visibility:hidden}
  .dm-igx-sh{display:none}
  .dm-igx-vw{display:inline-flex}
  .dm-igx-cr{display:none}
  .dm-igx-h{justify-content:space-between;padding-left:var(--dm-s-2)}
  .dm-igx-in:is([data-view="gallery"],[data-view="styles"]) .dm-igx-side{visibility:visible;z-index:2}
  .dm-igx-in:is([data-view="gallery"],[data-view="styles"]) :is(.dm-igx-feed,.dm-igx-cmp){visibility:hidden}
  .dm-igx-steps span:not(.dm-on){display:none}
  .dm-igx-pane{padding:var(--dm-s-3)}
  .dm-igx-gal{gap:var(--dm-s-2)}.dm-igx-col{gap:var(--dm-s-2)}
  .dm-igx-prs{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@container igx (max-width:440px){
  .dm-igx-in{height:640px}
  .dm-igx-feed{padding:var(--dm-s-3) var(--dm-s-3) var(--dm-s-2)}
  .dm-igx-ask{display:block;white-space:nowrap;text-overflow:ellipsis}
  .dm-igx-sty{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;gap:var(--dm-s-1)}
  .dm-igx-sty::-webkit-scrollbar{display:none}
  .dm-igx-sc{flex:none;padding:0 var(--dm-s-2)}
  .dm-igx-f>span{display:none}
  .dm-igx-cmp{margin:0 var(--dm-s-2) var(--dm-s-2)}
  .dm-igx-steps{display:none}
  .dm-igx-go{width:32px;padding:0}
  .dm-igx-go span{display:none}
  .dm-igx-meta{display:none}
  .dm-igx-prs{grid-template-columns:repeat(2,minmax(0,1fr))}
  .dm-igx-lbf .dm-igx-lbl{display:none}
  .dm-igx-lbn{display:none}
}
@container igx (max-width:340px){
  .dm-igx-bar .dm-chip>.dm-i:first-child{display:none}
  .dm-igx-bar .dm-chip{padding:0 var(--dm-s-2)}
}
/* Blueprint: square dots of the picture itself at half strength, a hard scan line in the accent's mark */
:root:not([data-style="soft"]) .dm-igx-t[data-st="gen"] .dm-igx-b:not(:where([data-style="soft"],[data-style="soft"] *)){opacity:.55;-webkit-mask:linear-gradient(90deg,#000 var(--dm-sq,2px),transparent 0) 0 0/var(--dm-cell,12px) var(--dm-cell,12px),linear-gradient(#000 var(--dm-sq,2px),transparent 0) 0 0/var(--dm-cell,12px) var(--dm-cell,12px);-webkit-mask-composite:source-in;mask:linear-gradient(90deg,#000 var(--dm-sq,2px),transparent 0) 0 0/var(--dm-cell,12px) var(--dm-cell,12px),linear-gradient(#000 var(--dm-sq,2px),transparent 0) 0 0/var(--dm-cell,12px) var(--dm-cell,12px);mask-composite:intersect}
:root:not([data-style="soft"]) .dm-igx-t.dm-up .dm-igx-b:not(:where([data-style="soft"],[data-style="soft"] *)){opacity:.45}
:root:not([data-style="soft"]) .dm-igx-l>span:first-child:not(:where([data-style="soft"],[data-style="soft"] *)){height:1px;top:0;background:var(--dm-accent-mark)}
:root:not([data-style="soft"]) .dm-igx-l>span:last-child:not(:where([data-style="soft"],[data-style="soft"] *)){display:none}
:root:not([data-style="soft"]) .dm-igx-t.dm-up .dm-igx-l:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .dm-igx-t.dm-up .dm-igx-s:not(:where([data-style="soft"],[data-style="soft"] *)){animation-timing-function:steps(14,end)}
