  .dm-igx .dm-igx-t:is([data-st="wait"],[data-st="gen"],[data-st="fail"]) .dm-igx-s{opacity:0}
  .dm-igx-g.dm-new,.dm-igx-lb.dm-open,.dm-igx-lb.dm-open .dm-igx-lbs>.dm-igx-t{animation:none}
